import { z } from "zod";

// One zod schema per knowledge base API response body — the runtime boundary (U8). The
// backend's pydantic models (engram/src/engram/retrieval/domain.py, served by
// studio/src/studio/knowledge_base/http/api.py) are the source of truth; these mirror
// them field-for-field so drift (a renamed field, a new required key, a type
// change) surfaces as a ZodError at `request()`'s `.parse()` on the failing
// endpoint rather than as `undefined.something` deep in a view.
//
// schema.d.ts (generated by `gen:types` from the FastAPI OpenAPI document) is the
// compile-time mirror of the same contract; this file is the runtime one. They
// are kept in lockstep by hand.

// -- graph (retrieval/domain.py Graph/GraphResult) ----------------------------

export const GraphNodeSchema = z.object({
  id: z.string(),
  type: z.string(),
  title: z.string(),
  status: z.string(),
  superseded: z.boolean(),
});

export const GraphEdgeSchema = z.object({
  src_id: z.string(),
  dst_id: z.string(),
  rel: z.string(),
  provenance_claim: z.string().nullable(),
});

export const GraphResultSchema = z.object({
  nodes: z.array(GraphNodeSchema),
  edges: z.array(GraphEdgeSchema),
});

export type GraphNode = z.infer<typeof GraphNodeSchema>;
export type GraphEdge = z.infer<typeof GraphEdgeSchema>;
export type GraphResult = z.infer<typeof GraphResultSchema>;

// -- registry of knowledge bases (studio/knowledge_base/http/api.py KnowledgeBaseListEntry/KnowledgeBaseListResult) ----

export const KnowledgeBaseListEntrySchema = z.object({
  name: z.string(),
  registered: z.boolean(),
  indexed: z.boolean(),
  broken: z.boolean(),
  path: z.string().nullable(),
  description: z.string(),
  pages: z.number().int().nullable(),
  page_types: z.array(z.string()),
  last_indexed: z.string().datetime({ offset: true }).nullable(),
});
export type KnowledgeBaseListEntry = z.infer<typeof KnowledgeBaseListEntrySchema>;

export const KnowledgeBaseListResultSchema = z.object({
  knowledge_bases: z.array(KnowledgeBaseListEntrySchema),
});
export type KnowledgeBaseListResult = z.infer<typeof KnowledgeBaseListResultSchema>;

// -- knowledge base detail (studio/knowledge_base/http/api.py KnowledgeBaseDetail, GET /api/knowledge-bases/{name}) ---

export const ValidationRowSchema = z.object({
  page_id: z.string(),
  severity: z.enum(["error", "warning"]),
  rule: z.string(),
  message: z.string(),
  anchor: z.string().nullable(),
});
export type ValidationRow = z.infer<typeof ValidationRowSchema>;

export const SourceQueueEntrySchema = z.object({
  key: z.string(),
  url: z.string(),
  source_type: z.enum(["video", "paper", "post", "article"]),
  status: z.enum(["requested", "resolved", "failed", "skipped"]),
  reason: z.string().nullable(),
  found_via: z.string().nullable(),
  found_at: z.string().datetime({ offset: true }).nullable(),
});
export type SourceQueueEntry = z.infer<typeof SourceQueueEntrySchema>;

// -- watch list (engram.sources.watch_list.domain WatchEntry, studio/knowledge_base/http/api.py watch-list routes) ----

export const WatchEntrySchema = z.object({
  scanner: z.string(),
  ref: z.string(),
  max_items: z.number(),
  last_scanned: z.string().datetime({ offset: true }).nullable(),
});
export type WatchEntry = z.infer<typeof WatchEntrySchema>;

export const RemoveWatchEntryResultSchema = z.object({ removed: z.boolean() });
export type RemoveWatchEntryResult = z.infer<typeof RemoveWatchEntryResultSchema>;

// -- decisions (engram/src/engram/retrieval/decisions.py DecidedPage, the GET .../decisions and
// PATCH .../pages/{page_id} routes) -------------------------------------------------------------

export const DecisionRowSchema = z.object({
  id: z.string(),
  page_type: z.string(),
  title: z.string(),
  summary: z.string(),
  status: z.string(),
  links: z.record(z.string(), z.array(z.string())),
});
export type DecisionRow = z.infer<typeof DecisionRowSchema>;

export const DecisionOutcomeSchema = z.object({
  status: z.string(),
  link: z.string().nullable(),
});
export type DecisionOutcome = z.infer<typeof DecisionOutcomeSchema>;

export const DecisionsSchema = z.object({
  rows: z.array(DecisionRowSchema),
  skipped: z.array(z.string()),
  outcomes_by_page_type: z.record(z.string(), z.array(DecisionOutcomeSchema)),
});
export type Decisions = z.infer<typeof DecisionsSchema>;

// The PATCH response: the page as it now reads, plus the ingest job the write enqueued.
export const DecisionResultSchema = DecisionRowSchema.extend({
  job_id: z.number(),
  index: z.enum(["queued", "in_progress"]),
});
export type DecisionResult = z.infer<typeof DecisionResultSchema>;

// -- coordination jobs (core/src/core/cqrs/ports.py Job, GET /api/jobs/{id}) --------------------

export const JobStateSchema = z.enum(["queued", "running", "failed", "done", "abandoned"]);
export type JobState = z.infer<typeof JobStateSchema>;

export const JobSchema = z.object({
  id: z.number(),
  kind: z.string(),
  key: z.string(),
  payload: z.record(z.string(), z.unknown()),
  state: JobStateSchema,
  attempts: z.number(),
  max_attempts: z.number(),
  available_at: z.string().datetime({ offset: true }),
  locked_at: z.string().datetime({ offset: true }).nullable(),
  locked_by: z.string().nullable(),
  lease_seconds: z.number(),
  last_error: z.string().nullable(),
  result: z.string().nullable(),
  created_at: z.string().datetime({ offset: true }),
  started_at: z.string().datetime({ offset: true }).nullable(),
  finished_at: z.string().datetime({ offset: true }).nullable(),
});
export type Job = z.infer<typeof JobSchema>;

// The 202 the refresh route answers: the job to watch, nothing about the run itself yet.
export const JobStartedSchema = z.object({ job_id: z.number() });
export type JobStarted = z.infer<typeof JobStartedSchema>;

// -- refresh runs and the schedule declaration (studio/knowledge_base/runs.py, settings.py Schedule) ----
// A refresh run is a finished job projected onto this shape, so a queued or running job has none yet.

export const RefreshRunSchema = z.object({
  started_at: z.string().datetime({ offset: true }),
  finished_at: z.string().datetime({ offset: true }),
  outcome: z.enum(["ok", "failed"]),
  detail: z.string(),
  trigger: z.enum(["manual", "schedule"]),
});
export type RefreshRun = z.infer<typeof RefreshRunSchema>;

export const RefreshRunsResultSchema = z.object({ refresh_runs: z.array(RefreshRunSchema) });
export type RefreshRunsResult = z.infer<typeof RefreshRunsResultSchema>;

// Exactly one of the two is set — the backend validates; the boundary just mirrors the shape.
export const ScheduleSchema = z.object({
  every_seconds: z.number().nullable().optional(),
  daily_at: z.string().nullable().optional(),
});
export type Schedule = z.infer<typeof ScheduleSchema>;

export const ScheduleReportSchema = z.object({
  name: z.string(),
  schedule: ScheduleSchema.nullable(),
});
export type ScheduleReport = z.infer<typeof ScheduleReportSchema>;

export const KnowledgeBaseDetailSchema = KnowledgeBaseListEntrySchema.extend({
  sources_connectors: z.array(z.string()),
  watch_list: z.array(WatchEntrySchema),
  validation: z.array(ValidationRowSchema),
  source_queue: z.array(SourceQueueEntrySchema),
  last_refresh_run: RefreshRunSchema.nullable(),
  schedule: ScheduleSchema.nullable(),
});
export type KnowledgeBaseDetail = z.infer<typeof KnowledgeBaseDetailSchema>;

// -- knowledge base registration (studio/knowledge_base/http/api.py RegistrationReport) --------

export const RegistrationReportSchema = z.object({
  name: z.string(),
  path: z.string(),
  description: z.string(),
  registered: z.boolean(),
});
export type RegistrationReport = z.infer<typeof RegistrationReportSchema>;

// -- knowledge base create (engram.init.domain.InitReport, the POST /api/knowledge-bases response) ----

export const InitReportSchema = z.object({
  written: z.array(z.string()),
  skipped: z.array(z.string()),
  merged: z.array(z.string()),
  forced: z.array(z.string()),
});
export type InitReport = z.infer<typeof InitReportSchema>;

// -- templates (engram.init.templates.Template, GET /api/templates) -----------------------------
// A named starting point the create dialog offers alongside "Minimal" and "Paste a knowledge-base
// schema JSON": `template` in a `POST /api/knowledge-bases` body names one of these by `slug`.

export const TemplateSchema = z.object({
  slug: z.string(),
  title: z.string(),
  path: z.string(),
});
export type Template = z.infer<typeof TemplateSchema>;

export const TemplatesResultSchema = z.object({
  templates: z.array(TemplateSchema),
});
export type TemplatesResult = z.infer<typeof TemplatesResultSchema>;

// -- knowledge base schema (engram.kb.domain.schema.KnowledgeBaseSchema, the GET /api/knowledge-bases/{name}/schema response) ----
//
// Mirrors KnowledgeBaseSchema field-for-field, STRICT: pydantic's model_dump_json always emits every
// field (including its default), so a response missing one is itself the contract drift this
// boundary exists to catch. Contrast KnowledgeBaseSchemaDraftSchema (create-dialog.tsx), which validates
// the OTHER direction — a person's minimally-filled-in schema on its way INTO a POST body, where
// only KnowledgeBaseSchema's own required fields must be present and everything else is the backend's job.

const FieldTypeSchema = z.enum(["scalar", "int", "scalar-list", "link", "link-list"]);

const FrontmatterFieldSpecSchema = z.object({
  name: z.string(),
  type: FieldTypeSchema,
  required: z.boolean(),
  choices: z.array(z.string()),
  default: z.union([z.string(), z.number()]).nullable(),
});

// A canonical section (engram.kb.domain.schema.CanonicalSection): a bare slug when the page type
// declares no display heading for it, or a {slug, heading} object when it does. The backend
// widened this from a plain string array, so both shapes are live — a headingless entry from an
// older knowledge-base-schema.json can still arrive as a bare string.
const CanonicalSectionSchema = z.union([
  z.string(),
  z.object({ slug: z.string(), heading: z.string().nullable() }),
]);

const PageTypeSpecSchema = z.object({
  page_type: z.string(),
  id_prefix: z.string(),
  folder: z.string().nullable(),
  folders: z.array(z.string()),
  files: z.array(z.string()),
  frontmatter_fields: z.array(FrontmatterFieldSpecSchema),
  status_values: z.array(z.string()),
  path_fields: z.array(z.string()),
  canonical_sections: z.array(CanonicalSectionSchema),
  edge_fields: z.array(z.string()),
  claims_enabled: z.boolean(),
  disclosed: z.boolean(),
});

const RelationDeclSchema = z.object({
  slug: z.string(),
  domain: z.string(),
  range: z.string(),
  symmetric: z.boolean(),
  qualifiers: z.array(z.array(z.string())),
  description: z.string(),
});

const VocabEntrySchema = z.object({
  value: z.string(),
  definition: z.string(),
});

const FacetSpecSchema = z.object({
  key: z.string(),
  scope: z.array(z.string()),
  seed: z.array(z.string()),
});

const ClaimGrammarSpecSchema = z.object({
  section: z.string(),
  edge_relations: z.array(z.string()),
  multilink_fields: z.array(z.string()),
  link_scalar_fields: z.array(z.string()),
  text_scalar_fields: z.array(z.string()),
  plain_fields: z.array(z.string()),
  quote_required_types: z.array(z.string()),
  comparative_relations: z.array(z.string()),
});

const SourcesSpecSchema = z.object({
  enabled: z.boolean(),
  quote_verify: z.boolean(),
  connectors: z.array(z.string()),
});

const RetrievalSpecSchema = z.object({
  profile: z.string(),
  collection: z.string(),
  disclosure_mode: z.enum(["strict", "search_only"]),
  group_by: z.enum(["app", "page_type"]).nullable(),
});

const SectionSummarySpecSchema = z.object({
  leading_sentences: z.number().int(),
  inline_gate_chars: z.number().int(),
});

const EmbedStrategiesSpecSchema = z.object({
  active: z.array(z.string()).nullable(),
  config: z.record(z.string(), z.record(z.string(), z.unknown())),
});

export const KnowledgeBaseSchemaSchema = z.object({
  version: z.string(),
  slug: z.string(),
  purpose: z.string(),
  slug_conventions: z.string(),
  page_types: z.array(PageTypeSpecSchema),
  relations: z.array(RelationDeclSchema),
  entity_types: z.array(VocabEntrySchema),
  claim_types: z.array(VocabEntrySchema),
  facets: z.array(FacetSpecSchema),
  claims: ClaimGrammarSpecSchema.nullable(),
  sources: SourcesSpecSchema,
  retrieval: RetrievalSpecSchema,
  section_summaries: SectionSummarySpecSchema,
  embed_strategies: EmbedStrategiesSpecSchema,
  path_root: z.enum(["parent", "knowledge_base"]),
});
export type KnowledgeBaseSchema = z.infer<typeof KnowledgeBaseSchemaSchema>;

// A proposed note, as data. It names its page type, what it says, and the fields the destination's
// schema declares, and it never names a file or a page id: the destination assigns those. The
// person may edit it, which is why the whole draft travels back on a keep rather than a patch.
export const NoteSectionSchema = z.object({
  heading: z.string(),
  body: z.string().default(""),
});
export type NoteSection = z.infer<typeof NoteSectionSchema>;

export const NoteDraftSchema = z.object({
  page_type: z.string(),
  title: z.string(),
  summary: z.string().default(""),
  frontmatter: z.record(z.string(), z.unknown()).default({}),
  sections: z.array(NoteSectionSchema).default([]),
});
export type NoteDraft = z.infer<typeof NoteDraftSchema>;

// What a destination would make of one proposed note, with nothing written. `preview_digest`
// covers the whole of it, so sending it back is what lets the host say whether this is still the
// note that was read, rather than taking the caller's word for it.
export const NotePreviewSchema = z.object({
  knowledge_base: z.string(),
  note_id: z.string(),
  draft: NoteDraftSchema,
  markdown: z.string(),
  path: z.string(),
  read_ref: z.string(),
  schema_digest: z.string(),
  preview_digest: z.string(),
  warnings: z.array(z.string()).default([]),
});
export type NotePreview = z.infer<typeof NotePreviewSchema>;

// What became of one keep that landed. `saved` wrote and indexed it. `saved_not_indexed` wrote it
// and the index did not run, so the same request again indexes it and writes nothing.
// `already_indexed` found it already kept and untouched. A path holding something else is a
// refusal rather than an outcome: the file is left exactly as it is and the host says so in its
// own sentence, which is what this app shows.
export const RetainedNoteSchema = z.object({
  outcome: z.enum(["saved", "saved_not_indexed", "already_indexed"]),
  knowledge_base: z.string(),
  note_id: z.string(),
  path: z.string(),
  read_ref: z.string(),
  detail: z.string().default(""),
  warnings: z.array(z.string()).default([]),
});
export type RetainedNote = z.infer<typeof RetainedNoteSchema>;
